using UnityEngine;
using UnityEngine.InputSystem;

// Reads the project-wide actions (Edit > Project Settings > Input System Package).
// Other scripts only use the properties below.
public class PlayerInputReader : MonoBehaviour
{
    private InputAction moveAction;
    private InputAction lookAction;
    private InputAction jumpAction;
    private InputAction sprintAction;
    private InputAction attackAction;
    private InputAction interactAction;

    public Vector2 Move { get; private set; }
    public Vector2 Look { get; private set; }
    public bool JumpPressed { get; private set; }
    public bool JumpHeld { get; private set; }
    public bool SprintHeld { get; private set; }
    public bool AttackPressed { get; private set; }
    public bool InteractPressed { get; private set; }

    private void Awake()
    {
        moveAction = InputSystem.actions.FindAction("Move");
        lookAction = InputSystem.actions.FindAction("Look");
        jumpAction = InputSystem.actions.FindAction("Jump");
        sprintAction = InputSystem.actions.FindAction("Sprint");
        attackAction = InputSystem.actions.FindAction("Attack");
        interactAction = InputSystem.actions.FindAction("Interact");
    }

    private void Update()
    {
        Move = moveAction != null ? moveAction.ReadValue<Vector2>() : Vector2.zero;
        Look = lookAction != null ? lookAction.ReadValue<Vector2>() : Vector2.zero;
        JumpPressed = jumpAction != null && jumpAction.WasPressedThisFrame();
        JumpHeld = jumpAction != null && jumpAction.IsPressed();
        SprintHeld = sprintAction != null && sprintAction.IsPressed();
        AttackPressed = attackAction != null && attackAction.WasPressedThisFrame();
        InteractPressed = interactAction != null && interactAction.WasPressedThisFrame();
    }
}

using UnityEngine;

// Third person with CharacterController: camera-relative movement, jump, gravity.
[RequireComponent(typeof(CharacterController), typeof(PlayerInputReader))]
public class ThirdPersonController : MonoBehaviour
{
    [SerializeField] private float walkSpeed = 4f;
    [SerializeField] private float sprintSpeed = 7f;
    [SerializeField] private float turnSpeed = 720f;   // degrees per second
    [SerializeField] private float jumpHeight = 1.2f;
    [SerializeField] private float gravity = -20f;
    [SerializeField] private Transform cameraTransform;

    private CharacterController controller;
    private PlayerInputReader input;
    private float verticalVelocity;

    private void Awake()
    {
        controller = GetComponent<CharacterController>();
        input = GetComponent<PlayerInputReader>();
        if (cameraTransform == null && Camera.main != null) cameraTransform = Camera.main.transform;
    }

    private void Update()
    {
        // Project the camera direction onto the ground
        Vector3 forward = Vector3.ProjectOnPlane(cameraTransform.forward, Vector3.up).normalized;
        Vector3 right = Vector3.ProjectOnPlane(cameraTransform.right, Vector3.up).normalized;
        Vector3 move = forward * input.Move.y + right * input.Move.x;
        move = Vector3.ClampMagnitude(move, 1f);

        if (move.sqrMagnitude > 0.001f)
        {
            Quaternion target = Quaternion.LookRotation(move, Vector3.up);
            transform.rotation = Quaternion.RotateTowards(transform.rotation, target, turnSpeed * Time.deltaTime);
        }

        if (controller.isGrounded && verticalVelocity < 0f) verticalVelocity = -2f; // keep grounded
        if (controller.isGrounded && input.JumpPressed) verticalVelocity = Mathf.Sqrt(jumpHeight * -2f * gravity);
        verticalVelocity += gravity * Time.deltaTime;

        float speed = input.SprintHeld ? sprintSpeed : walkSpeed;
        Vector3 velocity = move * speed + Vector3.up * verticalVelocity;
        controller.Move(velocity * Time.deltaTime);
    }
}

using UnityEngine;

// Checks whether this object can see the target (no wall in between).
public class LineOfSight : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private float viewDistance = 15f;
    [SerializeField] private LayerMask obstacles;

    public bool CanSeeTarget()
    {
        Vector3 toTarget = target.position - transform.position;
        if (toTarget.magnitude > viewDistance) return false;
        // Does the ray hit an obstacle before it reaches the target?
        return !Physics.Raycast(transform.position, toTarget.normalized, toTarget.magnitude, obstacles);
    }

    private void OnDrawGizmosSelected()
    {
        if (target == null) return;
        Gizmos.color = CanSeeTarget() ? Color.green : Color.red;
        Gizmos.DrawLine(transform.position, target.position);
    }
}

using UnityEngine;
using UnityEngine.Events;

// Health for the player or enemies. Other scripts call TakeDamage.
public class Health : MonoBehaviour
{
    [SerializeField] private int maxHealth = 5;
    public UnityEvent<int> onHealthChanged; // connect in the Inspector, e.g. to the health bar
    public UnityEvent onDied;

    public int Current { get; private set; }
    public int Max => maxHealth;

    private void Awake()
    {
        Current = maxHealth;
    }

    public void TakeDamage(int amount)
    {
        if (Current <= 0) return;
        Current = Mathf.Max(0, Current - amount);
        onHealthChanged?.Invoke(Current);
        if (Current == 0) onDied?.Invoke();
    }

    public void Heal(int amount)
    {
        Current = Mathf.Min(maxHealth, Current + amount);
        onHealthChanged?.Invoke(Current);
    }
}
